/* ---------- Modern Product Card ---------- */
const ProductCard = ({ item, index, navigation }) => {
  const anim = useRef(new Animated.Value(0)).current;
  const { addToCart } = useCart();

  useEffect(() => {
    Animated.spring(anim, {
      toValue: 1,
      friction: 7,
      tension: 40,
      delay: index * 50,
      useNativeDriver: true,
    }).start();
  }, [anim, index]);

  const translateY = anim.interpolate({ inputRange: [0, 1], outputRange: [50, 0] });
  const scale = anim.interpolate({ inputRange: [0, 1], outputRange: [0.9, 1] });

  // --- LOGIKA BARU UNTUK TOMBOL BELI ---
  const onBuy = () => {
    // 1. Masukkan produk ke cart
    addToCart(item, { qty: 1 });
    // 2. Langsung navigasi ke halaman Checkout
    navigation.navigate("Checkout");
  };

  const onAddCart = () => {
    addToCart(item, { qty: 1 });
    Alert.alert("Berhasil", `${item.name} masuk keranjang!`);
  };

  return (
    <Animated.View style={[styles.cardContainer, { opacity: anim, transform: [{ translateY }, { scale }] }]}>
      <TouchableOpacity activeOpacity={0.95} onPress={() => navigation.navigate?.("Detail", { product: item })} style={styles.card}>
        
        {/* Image Section */}
        <View style={styles.cardImageWrapper}>
          <Image source={{ uri: item.image }} style={styles.cardImage} />
          <View style={styles.ratingBadge}>
            <Ionicons name="star" size={10} color="#FFD166" />
            <Text style={styles.ratingText}>{item.rating}</Text>
          </View>
        </View>

        {/* Info Section */}
        <View style={styles.cardInfo}>
          <Text style={styles.cardTitle} numberOfLines={1}>{item.name}</Text>
          <Text style={styles.cardSeller} numberOfLines={1}>{item.sellerName}</Text>
          
          <View style={styles.priceRow}>
             <Text style={styles.cardPrice}>{item.price}</Text>
          </View>

          {/* Action Buttons Row */}
          <View style={styles.actionRow}>
            {/* Tombol Beli Langsung */}
            <TouchableOpacity onPress={onBuy} style={styles.btnBuy}>
              <Text style={styles.btnBuyText}>Beli</Text>
            </TouchableOpacity>
            
            {/* Tombol Tambah Keranjang */}
            <TouchableOpacity onPress={onAddCart} style={styles.btnCart}>
              <Ionicons name="cart-outline" size={18} color={PRIMARY_COLOR} />
            </TouchableOpacity>
          </View>
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
};

