/* ---------- Header with Logic ---------- */
function HomeHeader({ search, setSearch, navigation, selectedCategory, setSelectedCategory }) {
  const { totals } = useCart();
  const count = totals?.itemCount ?? 0;

  // Handler untuk memilih kategori
  const handleCategoryPress = (catId) => {
    // Jika diklik lagi kategori yang sama, maka deselect (toggle off)
    if (selectedCategory === catId) {
      setSelectedCategory(null);
    } else {
      setSelectedCategory(catId);
    }
  };

  return (
    <View style={styles.headerWrapper}>
      <StatusBar barStyle="light-content" backgroundColor={PRIMARY_COLOR} />
      
      {/* Background Curve Block */}
      <View style={styles.curvedBg}>
        {/* Top Bar Content */}
        <View style={styles.topBar}>
          <View>
            <Text style={styles.welcomeLabel}>Selamat Datang,</Text>
            <Text style={styles.welcomeName}>Julia Rokhmatur</Text>
          </View>
          
          <View style={styles.topIcons}>
            <TouchableOpacity 
              style={styles.iconBtn} 
              onPress={() => navigation.navigate("Notifikasi")}
            >
              <FontAwesomeIcon icon={faBell} size={18} color="#FFF" />
              <View style={styles.notifDot} />
            </TouchableOpacity>
            
            <TouchableOpacity 
              style={styles.iconBtn} 
              onPress={() => navigation.navigate?.("Keranjang")}
            >
              <FontAwesomeIcon icon={faCartShopping} size={18} color="#FFF" />
              {count > 0 && (
                <View style={styles.badge}>
                  <Text style={styles.badgeText}>{count}</Text>
                </View>
              )}
            </TouchableOpacity>
          </View>
        </View>

        {/* Search Bar - Floating */}
        <View style={styles.searchFloating}>
          <Ionicons name="search" size={20} color="#94A3B8" />
          <TextInput
            style={styles.searchInput}
            placeholder="Cari kebutuhan medis..."
            placeholderTextColor="#94A3B8"
            value={search}
            onChangeText={setSearch}
          />
          <TouchableOpacity style={styles.filterBtn}>
            <Ionicons name="options-outline" size={20} color={PRIMARY_COLOR} />
          </TouchableOpacity>
        </View>
      </View>

      {/* Content Below Curve */}
      <View style={styles.bodyContent}>
        
        {/* Banner Promo */}
        <View style={styles.bannerContainer}>
          <LinearGradient
            colors={["#42A5F5", "#1E88E5"]}
            start={{x: 0, y: 0}}
            end={{x: 1, y: 0}}
            style={styles.bannerGradient}
          >
            <View style={styles.bannerText}>
              <View style={styles.promoTag}>
                <Text style={styles.promoTagText}>PROMO 12.12</Text>
              </View>
              <Text style={styles.bannerTitle}>Diskon 50% All Item</Text>
              <Text style={styles.bannerSub}>Kesehatan prioritas utama.</Text>
            </View>
            <Image 
              source={{uri: "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTRWAAl6xL_1ZiSuvU4nxixZwQZdLkGTbqH4A&s"}} 
              style={styles.bannerImg}
            />
          </LinearGradient>
        </View>

        {/* Categories with Logic */}
        <View style={styles.sectionHeader}>
          <Text style={styles.sectionTitle}>Kategori</Text>
          {selectedCategory && (
            <TouchableOpacity onPress={() => setSelectedCategory(null)}>
               <Text style={styles.resetText}>Reset</Text>
            </TouchableOpacity>
          )}
        </View>
        <ScrollView 
          horizontal 
          showsHorizontalScrollIndicator={false} 
          contentContainerStyle={{ paddingHorizontal: 20, paddingBottom: 10 }}
        >
          {CATEGORY_DATA.map((item) => {
            const isActive = selectedCategory === item.id;
            return (
              <TouchableOpacity 
                key={item.id} 
                style={styles.catItem}
                onPress={() => handleCategoryPress(item.id)}
              >
                <View style={[
                  styles.catIconBox,
                  isActive && styles.catIconBoxActive // Style override jika aktif
                ]}>
                  <Ionicons 
                    name={item.icon} 
                    size={24} 
                    color={isActive ? PRIMARY_COLOR : "#FFF"} // Icon invert color
                  />
                </View>
                <Text style={[
                  styles.catText,
                  isActive && styles.catTextActive
                ]}>{item.label}</Text>
              </TouchableOpacity>
            );
          })}
        </ScrollView>

        {/* Product Section Title */}
        <View style={[styles.sectionHeader, { marginTop: 10 }]}>
          <Text style={styles.sectionTitle}>
            {selectedCategory ? `Filter: ${CATEGORY_DATA.find(c => c.id === selectedCategory)?.label}` : "Rekomendasi"}
          </Text>
          <TouchableOpacity onPress={() => setSelectedCategory(null)}>
             <Text style={styles.linkText}>Lihat Semua</Text>
          </TouchableOpacity>
        </View>

      </View>
    </View>
  );
}

/* ---------- Main Screen ---------- */
export default function Home({ navigation }) {
  const [search, setSearch] = useState("");
  const [selectedCategory, setSelectedCategory] = useState(null);

  // LOGIC FILTERING: Search text AND Category
  const filtered = PRODUCT_DATA.filter((p) => {
    const matchesSearch = 
      p.name.toLowerCase().includes(search.trim().toLowerCase()) ||
      p.sellerName.toLowerCase().includes(search.trim().toLowerCase());
    
    const matchesCategory = selectedCategory 
      ? p.categoryId === selectedCategory 
      : true;

    return matchesSearch && matchesCategory;
  });

  return (
    <View style={styles.mainContainer}>
      <FlatList
        data={filtered}
        keyExtractor={(item) => item.id}
        numColumns={2}
        columnWrapperStyle={styles.columnWrapper}
        contentContainerStyle={styles.listContainer}
        showsVerticalScrollIndicator={false}
        ListHeaderComponent={
          <HomeHeader 
            search={search} 
            setSearch={setSearch} 
            navigation={navigation}
            selectedCategory={selectedCategory}
            setSelectedCategory={setSelectedCategory}
          />
        }
        ListEmptyComponent={
          <EmptyState message={selectedCategory ? "Produk di kategori ini kosong." : "Produk tidak ditemukan."} />
        }
        renderItem={({ item, index }) => <ProductCard item={item} index={index} navigation={navigation} />}
      />
    </View>
  );
}

